import type { ChatMessageInput, SummaryPreprocessRule } from "../../shared/domain";

function expression(rule: SummaryPreprocessRule, forceGlobal = false): RegExp {
  let flags = [...new Set(rule.flags)].join("");
  if (forceGlobal && !flags.includes("g")) flags += "g";
  return new RegExp(rule.pattern, flags);
}

function extract(text: string, rule: SummaryPreprocessRule) {
  const matches = [...text.matchAll(expression(rule, true))];
  const parts = matches.flatMap((match) => {
    if (rule.extraction?.mode === "match") return [match[0]];
    if (rule.extraction?.mode === "group") return [match[rule.extraction.group] ?? ""];
    if (match.length <= 1) return match[0] ? [match[0].trim()] : [];
    return match.slice(1).filter(Boolean).map((value) => value.trim());
  });
  return { content: parts.filter(Boolean).join(rule.extraction?.separator ?? "\n"),
    matched: matches.length > 0,
    missingGroup: rule.extraction?.mode === "group" && matches.some((match) => match[rule.extraction!.group] === undefined) };
}

export interface CleaningReport {
  messages: ChatMessageInput[];
  notes: Array<{ messageId: string; rule: string; reason: string }>;
}

export function applySummaryPreprocess(
  messages: ChatMessageInput[],
  rules: SummaryPreprocessRule[],
): ChatMessageInput[] {
  return inspectSummaryPreprocess(messages, rules, false).messages;
}

export function inspectSummaryPreprocess(
  messages: ChatMessageInput[],
  rules: SummaryPreprocessRule[],
  includeNotes = true,
): CleaningReport {
  const notes: CleaningReport["notes"] = [];
  const ordered = [...rules]
    .filter((rule) => rule.enabled)
    .sort((left, right) => left.order - right.order || left.id.localeCompare(right.id));
  const result = messages.flatMap((message) => {
    if (message.role !== "user" && message.role !== "assistant") return [message];
    let content = message.content;
    for (const rule of ordered) {
      if (!rule.roles.includes(message.role)) continue;
      if (rule.type === "extract") {
        const extracted = extract(content, rule);
        if (includeNotes && (!extracted.matched || extracted.missingGroup)) notes.push({ messageId: message.id, rule: rule.name,
          reason: !extracted.matched ? "未匹配，保留结果为空" : "部分匹配中不存在指定捕获组或该组未参与匹配，对应片段为空" });
        content = extracted.content;
      } else {
        if (includeNotes && !expression(rule).test(content)) notes.push({ messageId: message.id, rule: rule.name, reason: "未匹配，内容未改变" });
        content = content.replace(expression(rule), rule.type === "remove" ? "" : rule.replacement);
      }
    }
    content = content.trim();
    return content ? [{ ...message, content }] : [];
  });
  return { messages: result, notes };
}
